{"name": "run_python", "parameters": {"code": "import csv, json
from io import StringIO
catalog = json.load(open("/data/CATALOG_CSV")).rows
values = csv.DictReader(StringIO(open("/data/VALUES_CSV").read()))
meter_id = next((x[\"timeseries_id\"] for x in catalog if x[\"point_class\"] == \"LIGHTING\"), None)
bld_meter_id = next((x[\"timeseries_id\"] for x in catalog if x[\"point_class\"] == \"BUILDING\"), None)
if meter_id is not None and bld_meter_id is not None:
    zone_lighting = 0
    bld_total = 0
    for v in values:
        if v[\"timeseries_id\"] == meter_id:
            zone_lighting += v[\"value\"]
        elif v[\"timeseries_id\"] == bld_meter_id and v[\"timestamp\"] == \"2018-01-09 00:00:00+\":
            bld_total += v[\"value\"]
    print(zone_lighting/bld_total)
else:
    print(\"Lighting meter or building meter not found\")"}}
